using namespace std;

int main() {
    int n, m, k;
    cin >> n >> m >> k;
    const int INF = 1e9;
    // dp[used]: minimum hours so far with `used` classes skipped
    vector<int> dp(k + 1, INF);
    dp[0] = 0;
    for (int r = 0; r < n; r++) {
        string row;
        cin >> row;
        vector<int> pos;
        for (int i = 0; i < m; i++)
            if (row[i] == '1') pos.push_back(i);
        int count = pos.size();
        // cost[skip]: shortest span keeping count-skip consecutive classes of this day
        vector<int> cost;
        for (int skip = 0; skip <= min(k, count); skip++) {
            int keep = count - skip, best = 0;
            if (keep > 0) {
                best = INF;
                for (int i = 0; i <= skip; i++) best = min(best, pos[i + keep - 1] - pos[i] + 1);
            }
            cost.push_back(best);
        }
        vector<int> nxt(k + 1, INF);
        for (int used = 0; used <= k; used++)
            for (int skip = 0; skip < (int)cost.size() && used + skip <= k; skip++)
                nxt[used + skip] = min(nxt[used + skip], dp[used] + cost[skip]);
        dp = nxt;
    }
    cout << *min_element(dp.begin(), dp.end()) << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), m = nextInt(), k = nextInt();
        final int INF = 1_000_000_000;
        // dp[used]: minimum hours so far with `used` classes skipped
        int[] dp = new int[k + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int r = 0; r < n; r++) {
            String row = next();
            int[] pos = new int[m];
            int count = 0;
            for (int i = 0; i < m; i++) if (row.charAt(i) == '1') pos[count++] = i;
            // cost[skip]: shortest span keeping count-skip consecutive classes of this day
            int limit = Math.min(k, count);
            int[] cost = new int[limit + 1];
            for (int skip = 0; skip <= limit; skip++) {
                int keep = count - skip, best = 0;
                if (keep > 0) {
                    best = INF;
                    for (int i = 0; i <= skip; i++) best = Math.min(best, pos[i + keep - 1] - pos[i] + 1);
                }
                cost[skip] = best;
            }
            int[] nxt = new int[k + 1];
            Arrays.fill(nxt, INF);
            for (int used = 0; used <= k; used++)
                for (int skip = 0; skip <= limit && used + skip <= k; skip++)
                    nxt[used + skip] = Math.min(nxt[used + skip], dp[used] + cost[skip]);
            dp = nxt;
        }
        System.out.println(Arrays.stream(dp).min().getAsInt());
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"slices"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, m, k := next(), next(), next()
	const INF = 1_000_000_000
	// dp[used]: minimum hours so far with `used` classes skipped
	dp := make([]int, k+1)
	for i := range dp {
		dp[i] = INF
	}
	dp[0] = 0
	for r := 0; r < n; r++ {
		sc.Scan()
		row := sc.Text()
		var pos []int
		for i := 0; i < m; i++ {
			if row[i] == '1' {
				pos = append(pos, i)
			}
		}
		count := len(pos)
		// cost[skip]: shortest span keeping count-skip consecutive classes of this day
		var cost []int
		for skip := 0; skip <= min(k, count); skip++ {
			keep, best := count-skip, 0
			if keep > 0 {
				best = INF
				for i := 0; i <= skip; i++ {
					best = min(best, pos[i+keep-1]-pos[i]+1)
				}
			}
			cost = append(cost, best)
		}
		nxt := make([]int, k+1)
		for i := range nxt {
			nxt[i] = INF
		}
		for used := 0; used <= k; used++ {
			for skip := 0; skip < len(cost) && used+skip <= k; skip++ {
				nxt[used+skip] = min(nxt[used+skip], dp[used]+cost[skip])
			}
		}
		dp = nxt
	}
	fmt.Println(slices.Min(dp))
}
